import csv, json, re, statistics as st
from collections import defaultdict
rows=list(csv.DictReader(open('data/scores.csv')))
tr={}
for line in open('data/judge_transcripts.jsonl'):
    d=json.loads(line); tr[d['rating_id']]=d
print(len(rows), len(tr))
mism=[]
for r in rows:
    t=tr.get(r['rating_id'])
    if t is None: mism.append(('missing',r['rating_id'])); continue
    m=re.search(r'FINAL SCORE:\s*(\d+)', t['judge_output'])
    fs=int(m.group(1))
    issues=[]
    if fs!=int(r['score']): issues.append(f"score {r['score']} vs FINAL {fs}")
    if t['response_id']!=r['response_id']: issues.append('resp id')
    if t['session']!=int(r['session']): issues.append('session')
    if t['displayed_label']!=r['displayed_label']: issues.append('label field')
    mm=re.search(r'Displayed author: ([\w-]+)', t['judge_output'])
    if mm and mm.group(1)!=r['displayed_label']: issues.append(f"output says {mm.group(1)}")
    if t['judge_model']!='atlas-7': issues.append('judge model '+t['judge_model'])
    if issues: mism.append((r['rating_id'],issues))
print('mismatches:',mism)
# pairing check
by=defaultdict(dict)
for r in rows: by[r['response_id']].setdefault(r['displayed_label'],[]).append((int(r['session']),int(r['score'])))
bad=[k for k,v in by.items() if set(v)!={'atlas-7','nova-3'} or any(len(x)!=1 for x in v.values())]
print('pairing problems:',bad)
diffs=[]
for k,v in sorted(by.items()):
    if 'atlas-7' in v and 'nova-3' in v:
        diffs.append(v['atlas-7'][0][1]-v['nova-3'][0][1])
print(diffs)
print('mean',sum(diffs)/len(diffs), 'sd',st.stdev(diffs), 'n',len(diffs))
# session balance
s=defaultdict(list)
for r in rows: s[(r['session'],r['displayed_label'])].append(int(r['score']))
for k in sorted(s): print(k,len(s[k]),round(sum(s[k])/len(s[k]),3))
print('nonzero', sum(1 for d in diffs if d!=0), 'pos',sum(1 for d in diffs if d>0),'neg',sum(1 for d in diffs if d<0))

